#!/usr/bin/env node
// settings-merge.js: build Cursor's User/settings.json from a shared and a local file.
//
//   node cursor/settings-merge.js [--dry-run]
//
// Cursor cannot include a second settings file, so scripts/setup.sh runs this to write one
// generated file from cursor/settings.json (shared, in git) and cursor/settings.local.json
// (private and machine-only keys, git-ignored, optional). Keys in the local file win. Nested
// objects merge key by key; arrays and other values are replaced. Both files may contain
// comments and trailing commas.
//
// Before it replaces the live file, it lists the live keys that the merge changes or drops (for
// example keys changed in the Cursor Settings UI) and saves the old file as settings.json.bak.
// With --dry-run it only lists them.

"use strict";

const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");

const SHARED = path.join(__dirname, "settings.json");
const LOCAL = path.join(__dirname, "settings.local.json");
const LIVE = path.join(os.homedir(), "Library", "Application Support", "Cursor", "User", "settings.json");
const LABEL = "  settings.json:";

const HEADER = [
    "// Generated by cursor/settings-merge.js in the dotfiles repo (scripts/setup.sh runs it) from",
    "// cursor/settings.json (shared) and cursor/settings.local.json (this machine, git-ignored).",
    "// Edit those files instead: the next run replaces this file. It lists the keys changed here",
    "// (for example in the Settings UI) before it does, and keeps the old file as settings.json.bak.",
].join("\n");

const STRING = String.raw`"(?:[^"\\]|\\.)*"`;
const COMMENT_RE = new RegExp(String.raw`(${STRING})|//[^\n]*|/\*[\s\S]*?\*/`, "g");
const TRAILING_COMMA_RE = new RegExp(String.raw`(${STRING})|,(\s*[}\]])`, "g");

function isObject(value) {
    return value !== null && typeof value === "object" && !Array.isArray(value);
}

// Parse JSONC (comments, trailing commas). Comments become spaces, so error positions still match.
function readSettings(file) {
    const json = fs
        .readFileSync(file, "utf8")
        .replace(/^﻿/, "")
        .replace(COMMENT_RE, (match, string) => string ?? match.replace(/[^\n]/g, " "))
        .replace(TRAILING_COMMA_RE, (_match, string, tail) => string ?? ` ${tail}`);
    let settings;
    try {
        settings = JSON.parse(json);
    } catch (error) {
        throw new Error(`${file}: ${error.message}`);
    }
    if (!isObject(settings)) throw new Error(`${file}: the top level is not an object`);
    return settings;
}

function merge(base, override) {
    const result = { ...base };
    for (const [key, value] of Object.entries(override)) {
        result[key] = isObject(result[key]) && isObject(value) ? merge(result[key], value) : value;
    }
    return result;
}

function equal(a, b) {
    if (a === b) return true;
    if (Array.isArray(a)) return Array.isArray(b) && a.length === b.length && a.every((item, i) => equal(item, b[i]));
    if (!isObject(a) || !isObject(b)) return false;
    const keys = Object.keys(a);
    return keys.length === Object.keys(b).length && keys.every((key) => Object.hasOwn(b, key) && equal(a[key], b[key]));
}

function show(value) {
    const text = JSON.stringify(value);
    return text.length > 80 ? `${text.slice(0, 77)}...` : text;
}

// Live keys whose value the merged result changes or drops. Nested objects are compared key by key.
function changedKeys(live, merged, prefix = "") {
    const changes = [];
    for (const [key, value] of Object.entries(live)) {
        const name = prefix + key;
        if (!Object.hasOwn(merged, key)) {
            changes.push(`${name}: ${show(value)} (not in the merged file)`);
        } else if (isObject(value) && isObject(merged[key])) {
            changes.push(...changedKeys(value, merged[key], `${name} > `));
        } else if (!equal(value, merged[key])) {
            changes.push(`${name}: ${show(value)} -> ${show(merged[key])}`);
        }
    }
    return changes;
}

function realpathOrNull(file) {
    try {
        return fs.realpathSync(file);
    } catch {
        return null;
    }
}

function main(args) {
    if (args.some((arg) => arg !== "--dry-run")) {
        console.error("usage: settings-merge.js [--dry-run]");
        return 2;
    }
    const dryRun = args.includes("--dry-run");

    const hasLocal = fs.existsSync(LOCAL);
    const merged = merge(readSettings(SHARED), hasLocal ? readSettings(LOCAL) : {});
    const text = `${HEADER}\n${JSON.stringify(merged, null, 4)}\n`;
    if (!hasLocal) console.log(`${LABEL} no cursor/settings.local.json (optional, see settings.local.example.json)`);

    let stat = null;
    try {
        stat = fs.lstatSync(LIVE);
    } catch (error) {
        if (error.code !== "ENOENT") throw error;
    }
    const target = stat ? realpathOrNull(LIVE) : null;

    if (stat?.isSymbolicLink() && (target === null || target === fs.realpathSync(SHARED))) {
        // The old setup symlinked cursor/settings.json (or the link is dangling): nothing to keep.
        console.log(`${LABEL} ${dryRun ? "would replace" : "replacing"} the old symlink with the merged file`);
    } else if (stat) {
        const old = fs.readFileSync(LIVE, "utf8");
        if (old === text) {
            console.log(`${LABEL} up to date`);
            return 0;
        }
        let changes;
        try {
            changes = changedKeys(readSettings(LIVE), merged);
        } catch (error) {
            changes = [`(cannot parse the live file: ${error.message})`];
        }
        if (changes.length > 0) {
            console.log(`${LABEL} these live keys differ from the merge and ${dryRun ? "would be" : "are"} replaced:`);
            for (const change of changes) console.log(`      ${change}`);
            console.log(`${LABEL} to keep them, put them in cursor/settings.json or cursor/settings.local.json`);
        }
        if (!dryRun) {
            fs.copyFileSync(LIVE, `${LIVE}.bak`);
            console.log(`${LABEL} saved the old file as settings.json.bak`);
        }
    }

    if (dryRun) {
        console.log(`${LABEL} dry run, nothing written`);
        return 0;
    }
    // Write a temp file and rename it over the live path: this replaces a symlink instead of
    // writing through it into the repo, and Cursor never reads a half-written file.
    fs.mkdirSync(path.dirname(LIVE), { recursive: true });
    const temp = `${LIVE}.tmp-${process.pid}`;
    fs.writeFileSync(temp, text);
    fs.renameSync(temp, LIVE);
    console.log(`${LABEL} written from cursor/settings.json${hasLocal ? " + cursor/settings.local.json" : ""}`);
    return 0;
}

try {
    process.exitCode = main(process.argv.slice(2));
} catch (error) {
    console.error(`settings-merge: ${error.message}`);
    process.exitCode = 1;
}
